'use strict';
const E=PulseEngine;
const money=n=>Math.round(n).toLocaleString('ko-KR')+'원';
const percent=p=>(p>0&&p<.01?(p*100).toFixed(3):(p*100).toFixed(1))+'%';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={fan:'light',budget:50000,budgetUnlimited:false,groupbuy:'compare',groupShipping_allmd:null,groupShipping_ktown:null,pob:'none',pobOffer:'auto',pobFormat:'any',pobKind:'any',pobPriority:'balanced',showcase:'none',showcaseTarget:1,goal:'balanced',collect:'keepsake',scope:'qr',trade:'yes',cap:3,music:'any',firstweek:'maybe'};
let answers={...defaults},prices={...E.defaultPrices},shipping=0,step=0,view='home',result=null;
let calcShop='auto';
let calcCounts={standard:0,limited:0,qr:0,qrset:1,wappen:0};
