const questions=[
  {key:'fan',title:'지금 리센느와 얼마나 가까운가요?',note:'구매 금액으로 팬심을 평가하지 않아요. 지금의 관심 정도만 알려 주세요.',options:[['light','노래가 좋아서 입문 중','일단 가볍게 한 장 소장하고 싶어요.'],['like','최애도 생겼고, 더 알아가는 중','마음에 드는 구성부터 골라 볼래요.'],['steady','꾸준히 챙겨 보는 팬','이번 앨범도 오래 소장하고 싶어요.'],['support','이번 활동을 적극 응원하고 싶어요','내 예산 안에서 계획적으로 참여할래요.']]},
  {key:'budget',title:'이번 구매에 편하게 쓸 수 있는 예산은?',note:'상품값과 설정한 배송·교환 예약액을 합친 상한입니다. 전부 쓸 필요는 없어요.',type:'budget'},
  {key:'goal',title:'하나만 고른다면, 무엇이 가장 중요한가요?',note:'추천 조합의 중심을 정하는 질문이에요.',options:[['balanced','골고루, 후회 없이','가격·포카·실물 소장을 함께 고려할래요.'],['book','포토북과 앨범 사진','크게 펼쳐 보고, 책장에 남기고 싶어요.'],['cards','포토카드','내가 좋아하는 얼굴을 손에 쥐는 게 먼저예요.'],['object','실물·굿즈 소장','리미티드 구성이나 와펜 같은 소장품이 좋아요.'],['chart','초동 판매량 응원','같은 예산이면 집계 가능 앨범 수를 우선할래요.']]},
  {key:'collect',title:'포카는 어디까지 모으고 싶나요?',note:'이 질문은 앨범 안의 봉입 포카 기준입니다. 판매처 특전은 다음 질문에서 따로 선택해요.',options:[['keepsake','들어 있는 포카면 충분해요','한 장의 추억이면 만족해요.'],['member','최애 멤버 중심으로 모을래요','원하는 멤버는 선택 구매나 교환을 이용할 수 있어요.'],['complete','한 버전의 앨범 포카를 전부','아래에서 수집할 버전을 선택해 주세요.'],['all','모든 버전의 앨범 포카를 전부','Standard·Limited·QR·Wappen의 포카 풀을 모을래요.']]},
  {key:'pob',title:'판매처 특전 포카도 필요한가요?',note:'첨부 자료의 7개 특전 세트와 배민·CU·메이크스타 단품 특전을 비교합니다. 특전은 일반 상품 페이지가 아닌 해당 이벤트 상품에서 구매해야 해요.',options:[['none','봉입 포카면 충분해요','특전 조건 없이 앨범 구성과 가격으로 추천해 주세요.'],['want','특전 포카도 갖고 싶어요','자동 추천 또는 아래에서 원하는 특전 상품을 골라 주세요.'],['all','첨부한 7개 특전 세트를 전부','상품 합계 564,200원 · 포함 실물 32개 · 배송비 별도입니다.']]},
  {key:'showcase',title:'쇼케이스 응모도 고려할까요?',note:'당첨 컷·경쟁률은 확인되지 않았어요. 목표 수량은 당첨 예상치가 아니라 내가 정한 신청 목표입니다. 11/03 20:00 KST 서울 행사에 참석할 수 있다면 선택해 주세요.',options:[['none','응모는 하지 않을래요','특전만 필요하면 이벤트 주문에서 응모하지 않아요를 선택할 수 있어요.'],['target','내가 정한 목표로 응모할래요','목표 충족을 먼저 고려하고, 예산·보관 상한을 지킵니다.'],['priority','응모 수량을 최우선으로 할래요','예산·보관 상한까지 이벤트 앨범 수량을 먼저 채웁니다.']]},
  {key:'trade',title:'랜덤 포카가 중복으로 나오면?',note:'교환을 할 수 있는지에 따라 필요한 수량과 추천 전략이 달라져요.',options:[['yes','교환할 수 있어요','같은 풀에서 1:1 교환이 성사된다는 가정의 최소 수량을 보여 줍니다.'],['no','교환 없이 직접 개봉하고 싶어요','완성 보장 수량은 없어요. 종류별 완성 확률을 함께 봅니다.'],['buy','부족한 포카만 따로 구할래요','중복 앨범보다 선택 구매를 우선하는 전략을 안내합니다.']]},
  {key:'cap',title:'실물 앨범은 최대 몇 개까지 보관할까요?',note:'QR 5종 세트는 5개로 셉니다. 와펜 상품도 보관 수량 1개로 포함해요.',options:[[1,'최대 1개','가볍게 한 장만 소장할래요.'],[3,'최대 3개','작은 조합이면 충분해요.'],[8,'최대 8개','여러 버전의 구성도 비교해 볼래요.'],[25,'최대 25개','포카 수집에 필요한 중복도 감수할 수 있어요.'],[50,'최대 50개','첨부한 특전 세트 전체와 추가 수집까지 고려할래요.'],['custom','직접 정할래요','1~100개 안에서 정확한 상한을 정해 주세요.']]},
  {key:'music',title:'앨범을 어떻게 즐길 계획인가요?',note:'와펜에는 공개 사양상 CD나 QR 음원 카드가 없어요.',options:[['any','소장이 목적이라 형식은 괜찮아요','사진과 구성품을 중심으로 추천해 주세요.'],['cd','실물 CD가 꼭 필요해요','예산이 허용하면 Standard 또는 Limited를 최소 1개 포함합니다.'],['listen','QR 음원도 괜찮아요','CD 또는 QR 음원 카드가 있는 상품을 포함합니다.']]},
  {key:'firstweek',title:'초동 반영은 얼마나 중요할까요?',note:'현재 예약 판매 중 · 발매 안내 2026.11.03. 집계는 판매처와 실제 출고·반영 시점에 달려요.',options:[['maybe','마음에 드는 앨범을 사는 게 먼저','초동은 참고만 할래요.'],['yes','내 구매도 초동에 들어갔으면 해요','초동 참여 체크리스트를 함께 보여 주세요.'],['main','이번 구매는 초동 응원이 최우선','구매 우선순위를 초동으로 바꾸고 수량을 최적화합니다.']]}
];
function persist(){try{localStorage.setItem('pulse-fit-v1',JSON.stringify({answers,prices,shipping}));}catch{}}
function validAnswers(input){
  if(!input||typeof input!=='object')return {...defaults};
  const a={...defaults};
  for(const key of ['fan','goal','trade','music','firstweek','showcase']){const q=questions.find(q=>q.key===key);if(q.options.some(o=>o[0]===input[key]))a[key]=input[key];}
  if(['compare','allmd','ktown'].includes(input.groupbuy))a.groupbuy=input.groupbuy;
  for(const g of E.groupBuys){const n=input['groupShipping_'+g.id];if(n===null||Number.isInteger(n)&&n>=0&&n<=1000000)a['groupShipping_'+g.id]=n;}
  if(typeof input.budgetUnlimited==='boolean')a.budgetUnlimited=input.budgetUnlimited;
  if(['none','want','all'].includes(input.pob))a.pob=input.pob;
  if(input.pobOffer==='auto'||E.pobOffers.some(o=>o.id===input.pobOffer))a.pobOffer=input.pobOffer;
  if(['any','single','set'].includes(input.pobFormat))a.pobFormat=input.pobFormat;
  if(['any','individual','unit'].includes(input.pobKind))a.pobKind=input.pobKind;
  if(['one','balanced','collect'].includes(input.pobPriority))a.pobPriority=input.pobPriority;
  const chosen=E.pobOffers.find(o=>o.id===a.pobOffer);if(chosen&&((a.pobFormat==='single'&&chosen.complete)||(a.pobFormat==='set'&&!chosen.complete)||(a.pobKind!=='any'&&chosen.giftKind!==a.pobKind)))a.pobOffer='auto';
  if(['keepsake','member','complete'].includes(input.collect))a.collect=input.collect;
  if(['standard','limited','qr','wappen','all'].includes(input.scope))a.scope=input.scope;
  if(Number.isInteger(input.budget)&&input.budget>=0&&input.budget<=2000000)a.budget=input.budget;
  if(Number.isInteger(input.cap)&&input.cap>=1&&input.cap<=100)a.cap=input.cap;
  if(Number.isInteger(input.showcaseTarget)&&input.showcaseTarget>=1&&input.showcaseTarget<=100)a.showcaseTarget=input.showcaseTarget;
  if(a.firstweek==='main')a.goal='chart';
  return a;
}
function loadState(value){if(!value||typeof value!=='object')return;answers=validAnswers(value.answers);if(value.prices)for(const p of E.catalog){const n=value.prices[p.id];if(Number.isInteger(n)&&n>=100&&n<=1000000)prices[p.id]=n;}if(Number.isInteger(value.shipping)&&value.shipping>=0&&value.shipping<=1000000)shipping=value.shipping;if(value.prices)for(const o of E.pobOffers.filter(o=>o.editablePrice)){const key='offer_'+o.id,n=value.prices[key];if(Number.isInteger(n)&&n>=100&&n<=1000000)prices[key]=n;}}
try{loadState(JSON.parse(localStorage.getItem('pulse-fit-v1')||'null'));}catch{}
function art(id){return `<div class="album-art ${id}" aria-hidden="true"><div class="album-book"><small>RESCENE</small><span>PULSE</span><small>${id==='wappen'?'WAPPEN':'4TH MINI'}</small></div></div>`;}
function go(next,focus=true){view=next;render();if(focus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}}
function render(){
  if(view==='home')home();else if(view==='quiz')quiz();else if(view==='compare')compare();else if(view==='calculator')calculator();else if(view==='pob')pobPage();else if(view==='result')results();
  document.querySelectorAll('.site-header nav button').forEach(b=>b.setAttribute('aria-current',b.dataset.view===view?'page':'false'));
}
function home(){const bare=E.barePrices(answers,prices);main.innerHTML=`
  <section class="hero"><div><span class="eyebrow">RESCENE PULSE / BUYING PROFILE TEST</span><h1>마음은 이미 <em>PULSE.</em><br>구매는 나답게.</h1><p class="hero-intro">포카가 먼저인가요, 포토북이 먼저인가요?<br>10가지 질문으로 나의 구매 성향을 알아보고,<br>예산에 맞는 앨범 포트폴리오를 받아 보세요.</p><button class="primary" data-view="quiz">나의 구매성향 진단하기 <span>↗</span></button><div class="hero-meta"><span>약 2분</span><span>10가지 질문</span><span>예산 안에서 추천</span></div></div>
  <div class="hero-art" aria-label="구매성향 보고서의 예시 디자인"><div class="art-grid"></div><span class="art-label">A LITTLE LOVE. A SMARTER PLAN.</span><div class="report-paper"><span class="tiny">PERSONAL ALBUM PORTFOLIO</span><h2>PULSE<br>your way.</h2><svg class="art-line" viewBox="0 0 220 50" aria-hidden="true"><path d="M0 26h42l13-17 20 34 17-28 13 11h27l11-9 12 9h65" stroke="#f47454" stroke-width="2" fill="none"/></svg><div class="art-row"><span>MY PRIORITY</span><b>포카와 포토북 사이</b></div><div class="art-row"><span>MY BUDGET</span><b>내가 편한 만큼</b></div><div class="art-row"><span>MY COLLECTION</span><b>나에게 맞는 조합</b></div><div class="art-chip">구매성향 진단<span>Find your fit.</span></div></div><div class="art-ticker"><span>01 — 05 / FIVE OPTIONS</span><span>YOUR TASTE, YOUR PACE ↗</span></div></div></section>
  <section><div class="section-rule"><h2>같은 PULSE, 다섯 가지 선택.</h2><button class="text-button" data-view="compare">구성 자세히 보기 ↗</button></div><div class="home-products">${E.catalog.map(p=>`<button class="mini-product" data-view="compare">${art(p.id)}<b>${p.name}</b><span>${p.tag}</span><span class="price">${money(bare.prices[p.id])}</span></button>`).join('')}</div><p class="data-note">${bare.groupVenue?bare.groupVenue.name+' 공구가 · 미공포 없음 · 배송비 별도. ':'공구 마감 · 일반 가격 참고. '}5개의 구매 옵션 = Standard · Limited · QR 단품 · QR 5종 세트 · Wappen. 세트는 QR 단품 5개이며, 별도의 포카 풀이 아닙니다. 위 이미지는 버전 구분을 위한 그림이며 실제 앨범 디자인이 아닙니다.</p><div class="notice">등급은 팬심의 크기가 아니라 구매 성향을 뜻해요. 더 많이 사는 것이 더 높은 팬 등급이라는 의미는 없습니다. 예산이 부족하면 구매 보류도 하나의 추천입니다.</div></section>`;}
function selectedValue(q){if(q.key==='collect'&&answers.collect==='complete'&&answers.scope==='all')return 'all';if(q.key==='cap'&&![1,3,8,25,50].includes(answers.cap))return 'custom';return answers[q.key];}
function groupOptions(){return [['compare','미공포 없는 수량은 두 공구가로 비교'],['allmd','미공포 없는 수량은 ALL MD 공구가'],['ktown','미공포 없는 수량은 Ktown4U 공구가']].map(([v,t])=>`<option value="${v}" ${answers.groupbuy===v?'selected':''}>${t}</option>`).join('');}
function groupFeeFields(){return E.groupBuys.map(g=>`<label class="price-field"><span>${g.name} 배송비 (미확인은 빈칸)</span><input name="groupShipping_${g.id}" id="fee-${g.id}" type="number" min="0" max="1000000" step="1" value="${answers['groupShipping_'+g.id]===null?'':answers['groupShipping_'+g.id]}" placeholder="실제 배송비 · 0은 무료배송 확인"></label>`).join('');}
function quiz(){
  const q=questions[step],selected=selectedValue(q);
  main.innerHTML=`<div class="quiz-layout"><aside class="quiz-side"><span class="eyebrow">INVEST IN YOUR TASTE</span><h1>나의 구매성향<br>알아보기.</h1><p>사기 전에, 나에게 물어볼 것들.<br>예산과 취향은 모두 달라도 괜찮아요.</p><div class="step-list">${steps.map((s,i)=>`<span class="step-item ${i===step?'active':''}"><span class="num">${String(i+1).padStart(2,'0')}</span>${s}${i<step?' ✓':''}</span>`).join('')}</div></aside><section class="quiz-panel"><div class="progress-top"><span>QUESTION ${String(step+1).padStart(2,'0')}</span><span>${step+1} / ${questions.length}</span></div><div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="${questions.length}" aria-valuenow="${step+1}" aria-label="진단 진행"><div style="width:${(step+1)/questions.length*100}%"></div></div><h2>${q.title}</h2><p class="question-note">${q.note}</p>
  ${q.type==='budget'?`<label class="field-label" for="budget-value">예산 (원)<input class="input-number" id="budget-value" type="number" min="0" max="2000000" step="100" value="${answers.budget}" inputmode="numeric" ${answers.budgetUnlimited?'disabled':''}></label><div class="budget-presets">${[20000,50000,100000,200000,400000].map(v=>`<button data-budget="${v}">${money(v)}</button>`).join('')}<button id="unlimited-budget" class="${answers.budgetUnlimited?'selected-budget':''}" aria-pressed="${answers.budgetUnlimited}">${answers.budgetUnlimited?'✓ ':''}예산 무제한</button>${answers.budgetUnlimited?'<button id="limited-budget">금액 직접 입력</button>':''}</div><p class="small muted" style="margin-top:20px">${answers.budgetUnlimited?'금액 제한 없음 · 보관 수량 상한은 유지합니다.<br>':''}배송·교환 예약액 ${money(shipping)} · <button class="text-button" data-settings>변경</button><br>현재 가격은 2026.10.13 확인값이며, 판매처 가격을 직접 바꿀 수 있어요.</p>`:
  `<div class="choices" role="radiogroup" aria-label="${q.title}">${q.options.map(([value,title,note])=>`<button type="button" class="choice ${value===selected?'selected':''}" role="radio" aria-checked="${value===selected}" data-choice="${value}"><span class="radio" aria-hidden="true"></span><span><b>${title}</b><small>${note}</small></span></button>`).join('')}</div>`}
  ${q.key==='budget'?`<label class="sub-options field-label">미공포 없는 앨범의 공구 구매처<select id="groupbuy-select">${groupOptions()}</select></label><p class="small muted">미공포 없는 앨범은 공구가로 예산을 계산합니다. 공구는 판매처 미공포·쇼케이스 응모 없이 일반 봉입 구성을 받습니다. 특전·응모에 필요한 앨범은 이벤트 상품을 유지합니다. ALL MD 공구 주문 상품값 5만 원 이상은 1회 무료배송 안내입니다.</p>${answers.groupbuy!=='none'?groupFeeFields()+'<p class="small muted">빈칸은 배송비 미확인입니다. 그때는 상품가 기준의 조건부 비교로 표시하며, 실제 배송비를 입력하면 예산에 포함해 다시 계산합니다. 별도 예약액에는 이 공구 배송비를 중복 입력하지 마세요.</p>':''}`:''}
  ${q.key==='collect'&&answers.collect==='complete'&&answers.scope!=='all'?`<label class="sub-options field-label">수집할 포카 풀<select id="scope-select">${[['qr','QR 전체 (공통 셀피 + 버전별)'],['standard','Standard (개인 + 유닛)'],['limited','Limited'],['wappen','Wappen']].map(([v,l])=>`<option value="${v}" ${answers.scope===v?'selected':''}>${l}</option>`).join('')}</select></label>`:''}
  ${q.key==='pob'&&answers.pob==='want'?`<label class="sub-options field-label">어떤 특전 조건을 원하나요?<select id="pob-format">${[['any','단품·세트 모두 비교'],['single','단품 · 랜덤 특전 1장이면 충분'],['set','중복 없는 특전 세트가 필요']].map(([v,l])=>`<option value="${v}" ${answers.pobFormat===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="sub-options field-label">어떤 특전 포카를 원하나요?<select id="pob-kind">${[['any','개인·유닛 모두 괜찮아요'],['individual','개인 미공포가 좋아요'],['unit','유닛 미공포가 좋아요']].map(([v,t])=>`<option value="${v}" ${answers.pobKind===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="sub-options field-label">특전 수집을 얼마나 중요하게 볼까요?<select id="pob-priority">${[['balanced','앨범 구성·봉입 포카와 함께 균형 있게'],['one','미공포 1종만 받으면 충분해요'],['collect','중복 없는 특전 수량의 비중을 높일래요']].map(([v,t])=>`<option value="${v}" ${answers.pobPriority===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="sub-options field-label">원하는 특전 상품<select id="pob-select"><option value="auto">내 우선순위에 맞춰 자동 추천</option>${E.pobOffers.filter(o=>(answers.pobFormat==='single'?!o.complete:answers.pobFormat==='set'?o.complete:true)&&(answers.pobKind==='any'||answers.pobKind===o.giftKind)).map(o=>`<option value="${o.id}" ${answers.pobOffer===o.id?'selected':''}>${o.seller} · ${o.name} · ${money(prices['offer_'+o.id]||o.price)}${o.complete?' · 중복 없는 세트':' · 특전 랜덤 1장'}</option>`).join('')}</select></label><p class="small muted">단품은 특전 1장 랜덤이며 전종 보장이 없습니다. 배민·CU의 단품 가격은 앱 직접 조회값이 아닌 기준가로 입력돼 있어요. 실제 상품값을 가격 설정에서 수정할 수 있습니다.</p>`:''}
  ${q.key==='showcase'&&answers.showcase!=='none'?`<div class="notice"><b>메이크스타 쇼케이스 상품만 자동 응모 계산</b><br>Standard 1개 ${money(E.showcaseEvent.price)} = 1회 · 5개 = 5회. 10/16 23:59 KST 마감. 일반 Standard·털실냥이 이벤트·배민·CU 상품은 응모 횟수에 넣지 않습니다. 후즈팬은 행사 상품을 안내하지만 응모 환산 조건을 확인하지 못해 자동 합산에서 제외합니다.</div>${answers.showcase==='target'?`<label class="sub-options field-label">내가 정한 응모 수량 (1~100개)<input id="showcase-target" type="number" min="1" max="100" step="1" value="${answers.showcaseTarget}" inputmode="numeric"></label><p class="small muted">기본값 1은 최소 신청 단위이며 권장 컷이 아닙니다. 목표가 예산·보관 상한을 넘으면 가능한 수량과 부족분을 보여 줍니다.</p>`:'<p class="small muted">수량 최우선은 예산을 상한까지 사용할 수 있어요. 금액 무제한일 때도 보관 수량 제한은 유지됩니다.</p>'}`:''}
  ${q.key==='cap'&&selected==='custom'?`<label class="field-label">최대 보관 수량 (1~100개)<input id="cap-value" type="number" min="1" max="100" value="${answers.cap}" inputmode="numeric"></label>`:''}
  <div id="quiz-error" class="error-text" role="alert"></div><div class="quiz-controls"><button class="back" id="quiz-back">${step===0?'홈으로':'← 이전 질문'}</button><button class="primary" id="quiz-next">${step===questions.length-1?'내 구매 보고서 보기':'다음 질문'} <span>↗</span></button></div></section></div>`;
  document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{let v=b.dataset.choice;if(q.key==='collect'){if(v==='all'){answers.collect='complete';answers.scope='all';}else{answers.collect=v;if(v==='complete'&&answers.scope==='all')answers.scope='qr';}}else if(q.key==='cap'){answers.cap=v==='custom'?12:Number(v);}else answers[q.key]=v;persist();quiz();});
  document.querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>{answers.budgetUnlimited=false;answers.budget=Number(b.dataset.budget);persist();quiz();});
  const unlimited=document.getElementById('unlimited-budget');if(unlimited)unlimited.onclick=()=>{answers.budgetUnlimited=true;persist();quiz();};
  const limited=document.getElementById('limited-budget');if(limited)limited.onclick=()=>{answers.budgetUnlimited=false;persist();quiz();};
  const groupSelect=document.getElementById('groupbuy-select');if(groupSelect)groupSelect.onchange=()=>{const b=document.getElementById('budget-value'),n=Number(b.value);if(b.value.trim()&&Number.isInteger(n)&&n>=0&&n<=2000000)answers.budget=n;answers.groupbuy=groupSelect.value;persist();quiz();};
  for(const g of E.groupBuys){const el=document.getElementById('fee-'+g.id);if(el)el.oninput=()=>{const n=Number(el.value);if(!el.value.trim())answers['groupShipping_'+g.id]=null;else if(Number.isInteger(n)&&n>=0&&n<=1000000)answers['groupShipping_'+g.id]=n;persist();};}
  const pobFormat=document.getElementById('pob-format');if(pobFormat)pobFormat.onchange=()=>{answers.pobFormat=pobFormat.value;answers.pobOffer='auto';persist();quiz();};
  const pobKind=document.getElementById('pob-kind');if(pobKind)pobKind.onchange=()=>{answers.pobKind=pobKind.value;answers.pobOffer='auto';persist();quiz();};
  const pobPriority=document.getElementById('pob-priority');if(pobPriority)pobPriority.onchange=()=>{answers.pobPriority=pobPriority.value;persist();};
  const pobSelect=document.getElementById('pob-select');if(pobSelect)pobSelect.onchange=()=>{answers.pobOffer=pobSelect.value;persist();};
  const scope=document.getElementById('scope-select');if(scope)scope.onchange=()=>{answers.scope=scope.value;persist();};
  document.getElementById('quiz-back').onclick=()=>{if(step>0){step--;quiz();}else go('home');};
  document.getElementById('quiz-next').onclick=()=>{
    if(q.key==='budget'&&answers.groupbuy!=='none')for(const g of E.groupBuys){const fee=document.getElementById('fee-'+g.id);if(fee&&fee.value.trim()&&(!Number.isInteger(Number(fee.value))||Number(fee.value)<0||Number(fee.value)>1000000)){document.getElementById('quiz-error').textContent='공구 배송비는 빈칸 또는 0~1,000,000원 정수로 입력해 주세요.';return;}}
    const el=document.getElementById(q.key==='budget'?'budget-value':q.key==='showcase'?'showcase-target':'cap-value');
    if(el&&!(q.key==='budget'&&answers.budgetUnlimited)){const n=Number(el.value),max=q.key==='budget'?2000000:100,min=q.key==='budget'?0:1;if(!el.value.trim()||!Number.isInteger(n)||n<min||n>max){document.getElementById('quiz-error').textContent=q.key==='budget'?'예산은 0~2,000,000원 사이의 정수로 입력해 주세요.':'수량은 1~100 사이의 정수로 입력해 주세요.';el.focus();return;}answers[q.key==='showcase'?'showcaseTarget':q.key]=n;}
    if(step===questions.length-1){if(answers.firstweek==='main')answers.goal='chart';persist();go('result');}else{persist();step++;quiz();main.focus({preventScroll:true});}
  };
}
function heading(tag,title,description,action=''){return `<div class="page-head"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function basketRows(m){return E.catalog.filter(p=>m.products[p.id]>0).map((p,i)=>`<div class="basket-row"><span class="index">${String(i+1).padStart(2,'0')}</span><div><b>${m.itemSources&&m.itemSources[p.id]?m.itemSources[p.id]+' · ':''}${p.name}</b><small>${p.id==='qrset'?'1세트 = QR 앨범 5개':p.tag}${m.itemSources&&m.itemSources[p.id]?' · 미공포·응모 없음':''}</small></div><span class="qty">${m.products[p.id]}${p.id==='qrset'?'세트':'개'}</span><span class="sum">${money(m.products[p.id]*(m.itemPrices||prices)[p.id])}</span></div>`).join('');}
function offerBasketRows(offers){return offers.map((o,i)=>`<div class="basket-row"><span class="index">P${i+1}</span><div><b>${o.seller} · ${o.name}</b><small>${o.additionalPurchase?'추가 수집용 · ':''}${o.gift}</small></div><span class="qty">${o.quantity||1}${o.complete?'세트':'개'}</span><span class="sum">${money(o.price)}</span></div>`).join('');}
function singleOffersTable(){return `<h3 style="margin-top:25px">단품으로 랜덤 특전 1장 받기</h3><div class="table-wrap"><table><thead><tr><th>판매처</th><th>앨범 단품</th><th>특전</th><th>상품값</th><th>확인 조건</th></tr></thead><tbody>${E.pobOffers.filter(o=>!o.complete).map(o=>`<tr><td>${o.seller}</td><td>${o.name}</td><td>${o.gift}<br><span class="small muted">중복 없는 전종 보장 없음</span></td><td>${money(prices['offer_'+o.id]||o.price)}<br><span class="small muted">${o.editablePrice?'기준가 · 앱 가격 확인':'공식 상품 표시가'}</span></td><td><a class="source-link" style="margin:0" href="${o.source}" target="_blank" rel="noopener noreferrer">판매처 확인 ↗</a><br><span class="small muted">${o.channel}</span></td></tr>`).join('')}</tbody></table></div><p class="data-note">배민·CU 단품의 랜덤 특전 1장 조건은 사용자 안내를 적용했고, CU는 공개된 예약 특전 안내와 대조했습니다. 단품 가격은 앱 상품 화면을 직접 확인하지 못해 기존 할인가·세트 단가 기준으로 산정했습니다. 실제 결제 가격은 가격 설정에서 수정하세요. CU는 10/14 15:00 오픈 예정 안내이며 한정 수량·예약 일정은 앱에서 확인해야 합니다. <a class="source-link" style="margin:0" href="https://www.youtube.com/post/UgkxutpUnwsxlK98JYC3GM9nKhLWSBpIVVKY" target="_blank" rel="noopener noreferrer">CU 특전 공개 안내 참고 ↗</a></p>`;}
function pobDataSection(){
  const complete=E.pobOffers.filter(o=>o.complete),total=complete.reduce((sum,o)=>sum+o.price,0);
  return `<section class="full-section" id="pob-data"><span class="eyebrow">PRE-ORDER PHOTOCARD GUIDE</span><h2 style="margin-top:10px">판매처별 특전, 따로 비교하기.</h2><p class="lead">첨부한 7개 세트 전체: 상품 합계 ${money(total)} · 포함 실물 32개 · 배송비 별도</p><div class="table-wrap"><table><thead><tr><th>판매처</th><th>상품 / 세트</th><th>특전 안내</th><th>상품 가격</th><th>구매 조건 확인</th></tr></thead><tbody>${complete.map(o=>`<tr><td>${o.seller}</td><td>${o.name}</td><td>${o.gift}<br><span class="small muted">${o.giftKind==='unit'?'유닛':'개인'} 특전 ${o.giftCount}장 · 중복 없는 세트 안내 기준</span></td><td>${money(o.price)}</td><td><a class="source-link" style="margin:0" href="${o.source}" target="_blank" rel="noopener noreferrer">${o.verified?'공식 상품 안내 ↗':'판매처 확인 ↗'}</a><br><span class="muted small">${o.channel}</span><br><span class="muted small">${o.verified?'증정 조건 대조':'첨부 자료 기준 · 조건 확인 필요'}</span></td></tr>`).join('')}</tbody></table></div>${singleOffersTable()}<div class="notice"><b>한 장만 사도 받을 수 있는 특전</b><br>메이크스타 털실냥이 이벤트는 Standard 단품 ${money(20800)} 구매에도 특전 5종 중 랜덤 1장을 줍니다. 한 주문에서 앨범 5개를 사면 중복 없는 특전 세트가 제공됩니다. <a class="source-link" style="margin:0" href="https://www.makestar.com/product/21195" target="_blank" rel="noopener noreferrer">공식 조건 ↗</a></div><p class="data-note">세트 안의 앨범은 봉입 포카 계산에도 포함됩니다. 사진에 없는 특전 도안 수는 임의로 추정하지 않았으며, 특전은 봉입 포카 확률과 합산하지 않습니다. 앱 판매·합배송·품절·주문 단위·이벤트 기간은 구매 전에 확인하세요. 쇼케이스 응모 상품 구매는 입장 당첨을 보장하지 않습니다. 일반 앨범 가격 설정은 위 특전 세트의 고정 상품값을 변경하지 않습니다. 배민·CU 단품의 기준가는 별도 항목에서 바꿀 수 있습니다.</p></section>`;
}
function pobPage(){main.innerHTML=heading('SPECIAL GIFTS / YOUR TASTE','특전까지 챙기는 구매 계획.','봉입 포카와 판매처 미공포는 다릅니다. 원하는 특전의 이벤트 상품을 선택하세요.',`<button class="primary" data-view="quiz">특전 포함 진단하기 ↗</button>`)+groupDataSection()+pobDataSection()+showcaseDataSection()+sourcesNote();}
function groupDataSection(){return `<section class="full-section"><span class="eyebrow">GROUP BUY / NO RETAILER POB</span><h2 style="margin-top:10px">총공 공구가까지 비교하기.</h2><p class="lead">사용자가 제공한 총공 안내 기준. 일반 봉입 구성은 같고, 판매처 미공포·쇼케이스 응모는 포함하지 않습니다.</p><div class="table-wrap"><table><thead><tr><th>구매 옵션</th><th>일반 기준가</th>${E.groupBuys.map(g=>`<th>${g.name}</th>`).join('')}</tr></thead><tbody>${E.catalog.map(p=>`<tr><td>${p.name}</td><td>${money(prices[p.id])}</td>${E.groupBuys.map(g=>`<td>${money(g.prices[p.id])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="collection-grid">${E.groupBuys.map(g=>`<article class="collection-card"><h3>${g.name}</h3><p>${E.groupOpen(g)?'구매 기간 중':'공구 마감'} · ${g.deadline}까지<br>${g.dispatch}<br>${g.gift}</p><p style="margin-top:12px">${g.freeShipping?'주문당 상품값 50,000원 이상 1회 배송비 무료, 100,000원 이상 분리배송 1회 신청 무료 안내. 다른 판매처 주문과 합산하지 않습니다.':'배송비 무료 기준은 첨부 자료에서 확인되지 않았습니다.'}</p><p style="margin-top:12px">회원가입과 총공 공지의 공구 전용 링크가 필요합니다. 일반 쇼핑몰 가격이 자동으로 이 공구가가 되지는 않습니다.</p></article>`).join('')}</div><div class="notice">ALL MD의 앨범 공구 사은품과 Ktown4U 팬버튼은 미공포가 아닙니다. ALL MD의 금액별 뷰티 사은품은 뷰티 상품 1개 이상 구매 조건이 있어 앨범만 구매하는 추천에 넣지 않습니다. 첨부 안내의 한터·CIRCLE 반영 문구는 함께 안내하지만, 와펜 상품별 반영은 기존처럼 확인 필요로 남깁니다. 11/04 이후 출고 안내만으로 초동 기간 내 반영을 확정하지 않습니다.</div></section>`;}
function groupResult(m){
  const g=m.groupVenue;
  if(m.empty)return '<div class="notice">공구 상품가와 입력한 배송비로 계산했지만 현재 예산·수량·필수 조건을 함께 충족하지 못했습니다.</div>';
  if(!g)return `<div class="notice">${m.groupExpired?'모든 공구가 마감되어 일반 가격을 참고값으로 표시합니다.': '이번 조합에는 미공포 없는 추가 구매가 없습니다. 특전·응모 상품만 해당 이벤트 가격으로 계산했습니다.'}</div>`;
  return `<section class="full-section"><h2>이번 조합의 공구 구매.</h2><p class="lead">${g.name} · 상품값 ${money(m.groupSubtotal)} · ${g.deadline}까지${m.groupFallback?' · 선택한 공구 마감으로 가능한 공구 적용':''}</p><div class="notice"><b>${m.groupShippingUnknown?'배송비 미확인 · 상품가 기준 조건부 추천':g.freeShipping&&m.groupSubtotal>=g.freeShipping?'이 공구 주문만 5만 원 이상 · 1회 무료배송':'입력한 공구 배송비 '+money(m.orderShipping)}</b><br>공구 상품은 봉입 포카·실물 수량에 포함하고 미공포·쇼케이스 응모에는 넣지 않습니다. ${g.dispatch}. ${m.groupShippingUnknown?'실제 배송비를 가격·배송비 설정에 입력하면 총 예산에 포함하여 판매처를 다시 비교합니다.':''}</div><p class="data-note">상품 ${money(m.total)} + 공구 배송비 ${m.groupShippingUnknown?'미확인':money(m.orderShipping)} + 별도 예약액 ${money(shipping)} = ${m.groupShippingUnknown?'현재 확인된 금액 ':''}${money(m.checkoutTotal)}. 다른 판매처 배송비는 별도 예약액으로 입력하세요. 공구 전용 구매 링크는 총공 공지에서 확인해야 합니다.</p></section>`;
}
function showcaseDataSection(){
  const e=E.showcaseEvent,status=E.showcaseStatus(),label={open:'응모 기간 중',upcoming:'응모 시작 전',closed:'응모 마감'}[status];
  return `<section class="full-section"><span class="eyebrow">SHOWCASE / PLAN YOUR LIMIT</span><h2 style="margin-top:10px">쇼케이스 응모도 구매 계획에.</h2><p class="lead">당첨 컷·경쟁률·수량별 당첨 확률은 알 수 없습니다. 구매 수량으로 당첨을 보장하지 않아요.</p><div class="collection-grid"><article class="collection-card"><span class="pill">${label}</span><h3>메이크스타 · 공식 조건 확인</h3><p>응모: 2026.10.13 15:00 ~ 10.16 23:59 KST<br>발표: 10.20 18:00 KST 이후 · 370명 선발<br>행사: ${e.date}<br>${e.venue}</p><div class="table-wrap"><table><thead><tr><th>이벤트 상품</th><th>상품값</th><th>응모</th><th>한입만 특전</th></tr></thead><tbody><tr><td>Standard 1개</td><td>${money(e.price)}</td><td>1회</td><td>5종 중 랜덤 1장</td></tr><tr><td>Standard 5개</td><td>${money(5*e.price)}</td><td>5회</td><td>한 주문이면 중복 없는 5장</td></tr></tbody></table></div><p>본 이벤트 상품의 결제 완료 수량만큼 응모하며, 동일 응모자의 여러 주문은 합산됩니다. 응모하지 않아요를 골라도 특전은 제공됩니다. 판매처 간 중복 당첨은 불가합니다.</p><a class="source-link" href="${e.source}" target="_blank" rel="noopener noreferrer">공식 응모 조건 ↗</a></article><article class="collection-card"><span class="pill">응모 환산 조건 확인 필요</span><h3>후즈팬 · 쇼케이스 상품 안내</h3><p>Standard 쇼케이스 단품 표시가 20,800원. 첨부 안내의 5개 특전 세트는 104,000원입니다. 이번 조회에서 이 행사의 응모 횟수 환산·마감·선발 인원을 모두 확인하지 못했습니다.</p><p style="margin-top:12px">후즈팬 상품은 특전·앨범 수량에 포함하되 메이크스타 응모 횟수와 합치지 않습니다. 원하는 판매처에서 실제 응모 규칙을 확인한 뒤 구매하세요.</p><a class="source-link" href="${E.pobOffers.find(o=>o.id==='whosfan-showcase').source}" target="_blank" rel="noopener noreferrer">후즈팬 쇼케이스 상품 확인 ↗</a></article></div><div class="notice">설문의 직접 입력 수량은 개인 목표입니다. 이 사이트는 안전 컷이나 당첨 확률을 추정하지 않습니다. 행사 응모는 해당 판매처에서 직접 진행해야 합니다. 일반 앨범·털실냥이 특전 구매는 쇼케이스 응모로 세지 않습니다. 기간이 지나면 자동 추천에서 추가 응모 구매를 중단합니다.</div></section>`;
}
function showcaseResult(m){
  const e=E.showcaseEvent,wants=answers.showcase!=='none',entries=m.showcaseEntries||0,potential=m.showcasePotential||0;
  const eventAlbums=(m.offers||[]).filter(o=>o.showcaseSeller);
  if(!wants&&!eventAlbums.length)return '';
  const before={open:'응모 가능 기간',upcoming:'아직 응모 시작 전',closed:'응모 마감'}[m.showcaseStatus];
  const max=answers.budgetUnlimited?answers.cap:Math.max(0,Math.min(answers.cap,Math.floor((answers.budget-shipping)/e.price)));
  return `<section class="full-section"><h2>쇼케이스 응모 계획.</h2><p class="lead">${before} · 메이크스타 공식 이벤트 기준 · 당첨 컷 미확인</p><div class="stats"><div class="stat"><span>${wants?'추천 조합의 응모 가능 횟수':'특전 구매 · 응모 선택 안 함'}</span><b>${wants?entries:0}<small>회</small></b></div><div class="stat"><span>${answers.showcase==='target'?'직접 정한 응모 목표':'응모 상품만 살 때 가능한 상한'}</span><b>${answers.showcase==='target'?answers.showcaseTarget:max}<small>${answers.showcase==='target'?'회':'개'}</small></b></div><div class="stat"><span>이벤트 Standard 1개</span><b>${money(e.price)}</b></div></div>${answers.showcase==='target'&&entries>answers.showcaseTarget?`<div class="notice">선택한 특전 상품에 포함된 응모 가능 수량이 개인 목표보다 ${entries-answers.showcaseTarget}회 많아요. 특전 조건을 충족하는 데 필요한 앨범이므로 그대로 포함했습니다. 실제 주문의 응모 선택을 확인하세요.</div>`:''}${m.showcaseShortfall?`<div class="notice coral-notice">개인 목표까지 ${m.showcaseShortfall}회 부족합니다. 예산·보관 상한·선택한 특전 조건을 유지한 조합이에요. 목표 수량은 당첨 컷이 아닙니다.</div>`:''}${wants&&m.showcaseStatus!=='open'?'<div class="notice coral-notice">현재는 응모 기간이 아니므로 추가 응모용 앨범을 추천에 넣지 않았습니다. 행사 일정과 구매 가능 여부를 판매처에서 확인하세요.</div>':''}<div class="notice">${!wants&&potential?`선택한 메이크스타 상품 ${potential}개는 기간 내 응모 선택 시 ${potential}회 신청할 수 있지만, 현재 답변에서는 응모를 원하지 않아 0회로 표시합니다. `:''}${entries?`메이크스타 이벤트 상품 ${entries}개만 응모로 계산했습니다. `:''}일반 Standard와 털실냥이 이벤트, 배민·CU의 상품은 포함하지 않습니다. ${eventAlbums.some(o=>o.showcaseSeller==='whosfan')?'후즈팬 쇼케이스 상품도 조합에 있지만 응모 환산을 확인하지 못해 위 횟수에서 제외했습니다. ':''}특전용 이벤트 앨범도 봉입 포카·실물 수량에 함께 반영했어요. 이 값은 구매 계획이며 실제 응모 완료 횟수가 아닙니다. 판매처에서 응모자 정보를 입력하고 결제해야 합니다.</div><p class="data-note">10/16 23:59 KST 마감 · ${e.date} · ${e.venue}. 선발 370명만으로 개인 당첨 확률을 계산할 수 없습니다. 판매처 간 중복 당첨은 불가하며, 5개 세트도 응모 5회입니다. <a class="source-link" style="margin:0" href="${e.source}" target="_blank" rel="noopener noreferrer">공식 이벤트 안내 ↗</a></p></section>`;
}
function pobResult(m){
  if(m.empty)return `<div class="notice coral-notice">선택한 특전 조건을 현재 예산·보관 수량·CD 조건과 함께 충족하지 못했습니다. 필요한 실물 수량과 예산을 조정하거나 다른 특전 상품을 골라 주세요.</div>`;
  return `<section class="full-section"><h2>이번 조합에서 받을 특전.</h2><p class="lead">${m.offers.length}개 이벤트 상품 항목 · 이벤트 상품 합계 ${money(m.bundleCost)} · 봉입 포카와 별도 증정 · 특전별 중복 없는 수량 합계 ${m.pobMetrics.guaranteedUnique}장 (안내 기준)</p><div class="table-wrap"><table><thead><tr><th>구매처 · 상품</th><th>예상 특전 조건</th><th>확인할 것</th></tr></thead><tbody>${m.offers.map(o=>`<tr><td>${o.seller}<br>${o.name}${o.quantity?' × '+o.quantity:''}</td><td>${o.gift}</td><td><a class="source-link" style="margin:0" href="${o.source}" target="_blank" rel="noopener noreferrer">구매 조건 확인 ↗</a><br><span class="small muted">${o.channel}</span></td></tr>`).join('')}</tbody></table></div><div class="notice">같은 앨범을 일반 판매처에서 사면 위 특전이 따라오지 않을 수 있어요. 해당 이벤트 상품에서 구매하고, 중복 없는 증정의 주문 단위·세트 조건을 확인하세요. 여러 판매처의 배송비를 합쳐 별도 지출 예약액에 입력해 주세요. 특전 수량은 사용자 안내의 앨범당 랜덤 1장·세트 중복 없음 조건을 적용합니다. CU QR 5개 세트는 개인 미공포 5장, CU 와펜 2개 세트는 유닛 미공포 2장으로 비교합니다. 같은 특전 세트의 반복 구매는 새로운 특전 5종으로 더하지 않습니다. 판매처·특전 종류별로 합산한 수량이며 전체 특전 도안을 대조한 전종 수가 아닙니다. 봉입 포카 장수·완성 확률에는 특전을 더하지 않습니다.</div></section>`;
}
function pobComparison(m){
  if(answers.pob!=='want'||answers.pobOffer!=='auto')return '';
  const byId=new Map();
  for(const c of m.candidateAudit||[]){if(c.ids.length!==1)continue;const key=c.ids[0],old=byId.get(key);if(!old||c.reason==='eligible'&&(old.reason!=='eligible'||c.score>old.score+1e-8||Math.abs(c.score-old.score)<1e-8&&c.total<old.total))byId.set(key,c);}
  const rows=[...byId.values()].map(c=>{const o=E.pobOffers.find(o=>o.id===c.ids[0]);return {o,c};});
  if(!rows.length)return '';
  return `<section class="full-section"><h2>특전 후보를 이렇게 비교했어요.</h2><p class="lead">CU QR 5종 세트도 같은 예산·보관 상한 안에서 다른 특전 후보와 비교합니다.</p><div class="table-wrap"><table><thead><tr><th>특전 상품</th><th>조건을 맞춘 조합 금액</th><th>특전별 중복 없는 수량</th><th>검토 결과</th></tr></thead><tbody>${rows.map(({o,c})=>`<tr><td>${o.seller} · ${o.name}<br><span class="small muted">${o.giftKind==='unit'?'유닛':'개인'} 특전</span></td><td>${c.reason==='eligible'?money(c.total)+(c.shippingUnknown?' + 미확인 공구 배송비':''):'상품 최소 '+money(c.minimumCost)}</td><td>${c.reason==='eligible'?c.guaranteedUnique+'장 (특전 종류별 합산)':'—'}</td><td>${c.reason==='capacity'?'보관 상한 초과 · 상품만 '+c.minimumUnits+'개':c.reason==='budget'?'상품만으로 예산 초과':c.reason==='requirements'?'CD·배송비 등 필수 조건 미충족':m.offers[0]&&m.offers[0].id===o.id?'선택한 성향과 조건에 맞춰 추천':'구매 가능 · 수량 우선순위·종합 점수·비용 비교에서 다른 조합 선택'}</td></tr>`).join('')}</tbody></table></div><p class="data-note">특전은 봉입 포카와 별도입니다. 랜덤 단품은 같은 특전 종류에서 최소 1종만 확보한 것으로 평가하고, 중복 없는 세트는 안내된 수량을 반영합니다. 개인·유닛 종류는 설문 선택으로 구분하며, 같은 특전을 여러 세트 사도 중복 없는 종류 수를 반복해 더하지 않습니다. 원하면 특전 상품을 직접 지정할 수 있습니다. 가중치는 취향을 반영하는 가이드이며, 쇼케이스 응모 최우선 조건은 먼저 유지합니다.</p></section>`;
}
function basketText(m){return E.catalog.filter(p=>m.products[p.id]>0).map(p=>`${p.name} ${m.products[p.id]}${p.id==='qrset'?'세트':'개'}`).join(' + ')||'구매 보류';}
function rationale(m){
  if(m.empty)return [];
  const r=[];
  if(answers.showcase==='priority')r.push(`쇼케이스 응모를 최우선으로 골라, 확인된 이벤트 상품 ${m.showcaseEntries}회분을 예산·보관 상한 안에서 먼저 반영했습니다. 당첨 컷을 가정하지 않았습니다.`);
  else if(answers.goal==='chart')r.push(`초동 최우선으로 설정해 집계 가능 앨범 수 ${m.chart}개를 먼저 최적화했습니다. QR 세트는 앨범 5개로 계산합니다.`);
  else if(answers.goal==='book')r.push('포토북 소장을 우선했습니다. Standard는 더 큰 판형이며, Limited의 페이지 수·사진 차이는 아직 확인되지 않았습니다.');
  else if(answers.goal==='object')r.push('포토북·리미티드 구성·와펜의 첫 소장을 우선하고 같은 실물의 반복 구매 효용은 낮게 계산했습니다.');
  else if(answers.goal==='cards')r.push('QR은 한 개에 포카 5장이 들어 있어 포카 중심의 조합에 유리합니다. 서로 다른 버전의 포카를 같은 수집 풀로 합치지 않았습니다.');
  else r.push('서로 다른 실물 구성의 첫 구매를 우선하고, 수집 목표가 없으면 반복 구매를 늘리지 않았습니다.');
  if(answers.showcase==='target')r.push(`직접 정한 ${answers.showcaseTarget}회 목표를 먼저 고려했습니다. 이벤트 앨범을 특전·봉입 포카 수집에 함께 활용하며 목표 수량은 당첨 컷이 아닙니다.`);
  if(answers.collect==='complete')r.push(answers.trade==='no'?'교환 없이 모으는 조건에서는 풀별 예상 수집 종류 수를 활용했습니다. 랜덤 개봉으로 완성을 보장할 수는 없습니다.':answers.trade==='buy'?'추가 앨범 반복 구매보다 부족한 도안의 선택 구매를 권합니다. 중고·분철 가격은 확인되지 않아 합계에 넣지 않았습니다.':'교환을 전제로 같은 풀 안에서 필요한 카드 수를 채우는 조합을 우선했습니다. 교환 성사와 비용은 별도로 확인해야 합니다.');
  if(answers.collect==='member')r.push('최애 중심 수집은 멤버 선택 가능 상품이나 교환이 효율적입니다. 기본 QR 단품은 버전 랜덤이므로 최애를 확정해 주지 않으며, 멤버별 도안 배분 미공개로 완성 수량을 단정하지 않습니다.');
  if(answers.music==='cd'&&m.books===0)r.push('현재 예산·수량에서는 CD 포함 상품을 살 수 없습니다. 이 조합은 CD 조건을 충족하지 못하므로 구매 보류 또는 예산 재설정을 권합니다.');
  if(m.initialCounts&&m.additionalCounts){
    const names={s:'Standard',l:'Limited',q:'QR',w:'Wappen'},scopeKeys={standard:['s'],limited:['l'],qr:['q'],wappen:['w'],all:['s','l','q','w']};
    const need=E.requirements(answers.scope,answers.trade==='no'?'no':'yes');
    for(const key of ['s','l','q','w'])if(m.initialCounts[key]>0&&m.additionalCounts[key]>0){
      const count=m.counts[key],collecting=answers.collect==='complete'&&(scopeKeys[answers.scope]||[]).includes(key);
      r.push(`${names[key]}은 특전·응모 상품에 든 ${m.initialCounts[key]}개를 이미 반영했고, ${collecting?'봉입 포카 수집 목표에 맞춰':'답변에서 정한 포카 수집 우선순위에 맞춰'} ${m.additionalCounts[key]}개를 더해 총 ${count}개입니다.${collecting?` ${answers.trade==='no'?'풀별 완성 확률 90% 참고 수량':'교환 전제 최소 수량'}은 ${need[key]}개${count<need[key]?'로, 현재 조합은 '+(need[key]-count)+'개 부족한 부분 수집 계획입니다': '이며 완성은 보장하지 않습니다'}.`:''}`);
    }
  }
  if(answers.pob!=='none'&&m.pobMetrics)r.push(answers.pobPriority==='one'?'미공포 1종이면 충분하다는 답변을 반영해 특전 수량만으로 구매를 늘리지 않았습니다.':`봉입 포카·앨범 구성에 더해, 판매처·특전별로 중복 없이 확보하는 수량 ${m.pobMetrics.targetUnique}장도 ${answers.pobPriority==='collect'?'비중을 높여':'함께'} 평가했습니다. 같은 특전의 반복 구매로 중복 없는 수량이 늘어난다고 가정하지 않았습니다.`);
  if(m.offers.some(o=>o.additionalPurchase))r.push('추가 앨범도 같은 구성·같거나 낮은 가격의 특전 상품이 있으면 선택한 판매처로 연결했습니다. 단품 특전은 랜덤이며 기존 미공포와 중복될 수 있습니다. 앱 기준가는 실제 가격·증정 기간을 확인하세요.');
  if(m.offers.length)r.push(`특전·응모 상품의 앨범도 봉입 포카와 보관 수량에 한 번씩 포함했습니다. 추가 수량은 수집 목표와 예산 안에서 계산했습니다. 특전과 봉입 포카는 구분하며, 판매처별 배송비·응모 조건은 따로 확인하세요.`);
  if(m.groupVenue)r.push(`판매처 특전·응모에 필요한 상품을 먼저 확보하고, 나머지는 ${m.groupVenue.name}의 미공포 없는 공구가로 비교했습니다. 공구 물량을 응모 횟수로 세지 않습니다.`);
  r.push(`상품 ${money(m.total)} + 공구 배송비 ${m.groupShippingUnknown?'미확인':money(m.orderShipping||0)} + 별도 예약액 ${money(shipping)} = ${money(m.checkoutTotal)}${m.groupShippingUnknown?' + 미확인 배송비':''}. 예산 ${answers.budgetUnlimited?'무제한':money(answers.budget)}와 보관 상한 ${answers.cap}개 안에서 비교했습니다.`);
  return r;
}
function scopedPoolRows(c,m,scope='all'){
    return E.pools(c,prices,m.qrsets).filter(p=>scope==='all'||scope===p.key).map(p=>`<tr><td>${p.name}${p.versions?'<br><span class="muted small">총 5개 풀, 같은 값으로 표시</span>':''}</td><td>${p.n}종 중 ${p.k}장</td><td>${p.packs}회</td><td>${p.expected.toFixed(1)} / ${p.n}종</td><td><span class="prob-bar"><i style="width:${p.probability*100}%"></i></span>${percent(p.probability)}</td></tr>`).join('');
}
function probabilityNote(){return `<p class="data-note">확률 모형: 한 팩 안에서는 중복 없는 균등 추출, 팩 간에는 독립 추출을 가정했습니다. 실제 배봉·재고에 따라 달라질 수 있습니다. 완성 확률은 각 포카 풀 단위이며, 모든 풀을 동시에 완성할 확률이 아닙니다. QR 버전별 계산은 5종 세트로 확보한 각 버전 수량만 사용하고 랜덤 단품은 제외합니다.</p>`;}
function results(){
  const effective=answers.trade==='buy'?{...answers,collect:answers.collect==='complete'?'member':answers.collect}:answers;
  result=E.recommend(effective,prices,shipping);const m=result,p=E.profile(answers),bareUnitPrices=E.barePrices(answers,prices).prices;
  const remaining=answers.budgetUnlimited?null:Math.max(0,answers.budget-(m.empty?0:m.checkoutTotal));
  const meters=[['포카',answers.goal==='cards'||answers.collect==='complete'?90:answers.collect==='member'?70:35],['실물 소장',['book','object'].includes(answers.goal)?90:answers.music==='cd'?70:45],['초동',answers.goal==='chart'?95:answers.firstweek==='yes'?65:25]];
  main.innerHTML=heading('YOUR PERSONAL ALBUM PORTFOLIO','나의 PULSE 구매 보고서.','취향을 먼저, 예산은 편안하게. 결과는 언제든 다시 조정할 수 있어요.',`<button class="secondary" id="redo">답변 다시 보기 ↗</button>`)+`
  <div class="result-layout"><aside class="profile-card"><span class="eyebrow">BUYING PROFILE / TYPE ${p.grade}</span><span class="grade">${p.grade}</span><h2>${p.name}</h2><p>${p.line}</p><div class="profile-meter">${meters.map(([name,n])=>`<div class="meter-row"><span>${name}</span><div class="meter"><div style="width:${n}%"></div></div><span>${n}</span></div>`).join('')}</div><p class="profile-small">숫자는 답변을 요약한 성향 표시입니다.<br>팬심 점수나 구매 권장 강도를 뜻하지 않아요.</p></aside>
  <section class="recommend-card"><div class="recommend-top"><h2>${m.empty?'지금은 구매 보류':'이 조합을 추천해요.'}</h2><span class="sticker">${m.empty?'BUDGET FIRST':'YOUR FIT'}</span></div>
  ${m.empty?`<div class="empty"><p>${m.pobBlocked?`선택한 특전 조건을 현재 예산·보관 상한 안에서 충족할 수 없어요. 선택한 특전 상품만으로 실물 최소 ${m.minimumPobUnits}개, 상품 최소 ${money(m.minimumPobCost)}가 필요합니다. CD 필수 조건과 별도 배송 예약액도 확인해 주세요.`:'현재 예산과 예약액 안에서 조건에 맞는 상품을 고를 수 없어요.'} 가장 저렴한 단품은 ${money(Math.min(bareUnitPrices.standard,bareUnitPrices.limited,bareUnitPrices.qr,bareUnitPrices.wappen))}입니다. 예약액·CD 조건도 함께 확인해 주세요.</p></div>`:`<div class="basket-list">${m.offers.length?offerBasketRows(m.offers)+basketRows(m.extras):basketRows(m)}</div><div class="basket-total"><div><span class="eyebrow">ALBUM SUBTOTAL</span><span class="small muted">별도 예약액 ${money(shipping)}${m.groupVenue?' · 공구 배송비 '+(m.groupShippingUnknown?'미확인':money(m.orderShipping)):''}</span></div><strong class="total-price">${money(m.total)}</strong></div><div class="stats"><div class="stat"><span>보관할 실물 수량</span><b>${m.units}<small>개</small></b></div><div class="stat"><span>봉입 포카 수량 · 중복 포함</span><b>${m.cards}<small>장</small></b></div><div class="stat"><span>${m.groupShippingUnknown?'배송비 확인 전 잔액':'남겨 둔 예산'}</span><b>${answers.budgetUnlimited?'제한 없음':money(remaining)}</b></div></div><ul class="reason-list">${rationale(m).map(t=>`<li>${t}</li>`).join('')}</ul>`}
  <div class="budget-edit"><label for="result-unlimited"><input id="result-unlimited" type="checkbox" ${answers.budgetUnlimited?'checked':''}> 예산 무제한</label><label for="result-budget">금액 다시 계산</label><input id="result-budget" type="number" min="0" max="2000000" value="${answers.budget}" inputmode="numeric" ${answers.budgetUnlimited?'disabled':''}><button class="text-button" id="recalculate">적용 ↗</button><button class="text-button" data-settings>가격 변경</button></div><div id="result-error" class="error-text" role="alert"></div></section></div>
  ${!m.empty?`<section class="full-section"><h2>수량을 정하기 전에, 이것까지.</h2><p class="lead">봉입 포카 수량과 서로 다른 도안 수는 다릅니다.</p><div class="collection-grid"><article class="collection-card"><span class="eyebrow">LESS IS ALSO A PLAN</span><h3>한 장부터 시작하기</h3><div id="light-plan"></div></article><article class="collection-card"><span class="eyebrow">FIRST-WEEK CHECK</span><h3>집계 가능 수량 ${m.chart}개 <span class="small muted">(예상)</span></h3><p>Standard·Limited·QR 단품은 각각 1개, QR 5종 세트는 5개로 계산합니다. 와펜 ${m.products.wappen}개는 반영 여부가 확인되지 않아 제외했습니다.</p><p style="margin-top:13px">판매처의 한터 반영 안내, 초동 기간 내 출고·집계, 세트 수량 반영을 확인하세요. 주문·결제만으로 초동 반영을 확정할 수는 없습니다.</p></article></div></section>`:''}
  ${m.offers.length?pobResult(m):''}
  ${pobComparison(m)}
  ${groupResult(m)}
  ${showcaseResult(m)}
  ${answers.collect==='complete'?collectionRoadmap(m):''}
  ${answers.collect==='member'?`<div class="notice coral-notice"><b>최애 수집 팁</b><br>최애 도안이 꼭 필요하면 랜덤 개봉을 반복하기보다 패키지 선택·앨범 분철·포카 교환을 먼저 확인하세요. QR 단품의 최애 패키지 확률과 최애 포카 배분은 서로 다릅니다. 현재 공개 사양만으로 멤버별 완성 수량을 확정하지 않았습니다.</div>`:''}
  ${!m.empty?`<section class="full-section"><h2>이 조합의 포카 수집 전망</h2><div class="table-wrap"><table><thead><tr><th>수집 풀</th><th>한 번에 받는 구성</th><th>개봉 횟수</th><th>예상 도안 수</th><th>교환 없이 완성할 확률</th></tr></thead><tbody>${scopedPoolRows(m.counts,m)}</tbody></table></div>${probabilityNote()}</section>`:''}
  <div class="button-row result-actions"><button class="primary" id="copy-result">결과 요약 복사 ↗</button><button class="secondary" id="share-result">같은 결과 링크 복사 ↗</button><button class="secondary" id="print-result">보고서 저장 / 인쇄 ↗</button><button class="text-button" id="open-result-calc">수량 직접 바꿔 보기</button></div>${sourcesNote()}`;
  document.getElementById('redo').onclick=()=>{step=0;go('quiz');};
  document.getElementById('result-unlimited').onchange=event=>{answers.budgetUnlimited=event.target.checked;persist();results();};
  document.getElementById('recalculate').onclick=()=>{if(answers.budgetUnlimited){results();return;}const el=document.getElementById('result-budget'),n=Number(el.value);if(!el.value.trim()||!Number.isInteger(n)||n<0||n>2000000){document.getElementById('result-error').textContent='0~2,000,000원 사이의 정수로 입력해 주세요.';return;}answers.budget=n;persist();results();};
  if(!m.empty){const light=E.recommend({...effective,collect:'keepsake',showcase:'none',cap:1},prices,shipping);document.getElementById('light-plan').innerHTML=light.empty?'<p>현재 조건에서 한 개 구매가 어려워요.</p>':`<div class="line-items">${basketText(light)}</div><div class="amount">${money(light.total)}</div><p>우선 하나를 소장한 뒤, 실제 사진과 포카 도안을 보고 다음 구매를 정해도 좋아요.</p>`;}
  document.getElementById('copy-result').onclick=()=>copyText(summaryText());
  document.getElementById('share-result').onclick=()=>copyText(location.origin+location.pathname+'#r='+encodeURIComponent(JSON.stringify({answers,prices,shipping})));
  document.getElementById('print-result').onclick=()=>window.print();
  document.getElementById('open-result-calc').onclick=()=>{calcCounts={...m.products};calcShop=m.groupVenue?m.groupVenue.id:'auto';go('calculator');};
}
function collectionRoadmap(m){
  const scope=answers.scope,minimum=E.requirements(scope,'yes');
  const reference=E.barePrices(answers,prices),roadmapPrices=reference.prices;
  const full=E.metrics(minimum,roadmapPrices,shipping,true),direct=E.metrics(E.requirements(scope,'no'),roadmapPrices,shipping,true);
  const over=answers.budgetUnlimited?0:Math.max(0,full.total+shipping-answers.budget);
  const short=E.catalog.filter(p=>full.products[p.id]>0).map(p=>`${p.name} ${full.products[p.id]}${p.id==='qrset'?'세트':'개'}`).join(' + ');
  const scopeNames={standard:'Standard 개인·유닛',limited:'Limited',qr:'QR 공통·버전별',wappen:'Wappen',all:'모든 버전'};
  return `<section class="full-section"><h2>${scopeNames[scope]} 포카, 끝까지 모으려면?</h2><p class="lead">${reference.groupVenue?reference.groupVenue.name+' 공구 상품가 기준 · 배송비 별도. ':'공구 마감 · 일반 가격 참고. '}봉입 포카만의 최소 수량 참고값입니다. 특전 세트에 들어 있는 앨범도 위 추천에서 합산되며, 아래 수량을 추가로 전부 사야 한다는 뜻은 아닙니다. 완성은 보장되지 않습니다.</p><div class="collection-grid"><article class="collection-card"><span class="eyebrow">WITH TRADES / THEORETICAL MINIMUM</span><h3>교환 전제 최소 ${full.units}개</h3><div class="line-items">${short}</div><div class="amount">${money(full.total)} <span class="small muted">상품 합계</span></div><p>${scope==='qr'||scope==='all'?'QR은 패키지별 4종 중 2장씩이므로 각 패키지 2개, 즉 5종 세트 2세트가 필요합니다. 공통 셀피도 총 30장을 받아 15종 교환 재료를 확보합니다. ':''}각 풀에서 카드 장수를 채운 뒤 1:1 교환이 가능하다는 가정입니다. 도안·인기 차이에 따라 교환이 성사되지 않을 수 있어요.</p><div class="tag-row"><span class="pill">${over>0?'예산보다 '+money(over)+' 초과':'현재 예산 안'}</span><span class="pill">${full.units>answers.cap?'보관 상한 초과':'보관 상한 안'}</span></div>${over>0||full.units>answers.cap?'<p>목표 수량 참고용입니다. 위 추천 조합은 현재 예산·수량 제한을 지킵니다.</p>':''}</article><article class="collection-card"><span class="eyebrow">WITHOUT TRADES / RANDOM DRAWS</span><h3>풀별 완성 확률 90% 기준</h3><div class="line-items">${basketText(direct)}</div><div class="amount">${money(direct.total)} <span class="small muted">상품 합계</span></div><p>각 풀의 완성 확률이 90% 이상이 되도록 필요한 수량입니다. 모든 풀을 동시에 완성할 확률 90%를 뜻하지 않습니다. 이 수량을 사도 누락 도안이 나올 수 있습니다.</p><p style="margin-top:10px">예산·보관 상한과 무관한 확률 참고값입니다. 중복 구매를 계속하기보다 필요한 도안만 교환·선택 구매하는 방법도 고려하세요.</p></article></div><div class="notice">수집 범위는 봉입 <b>포토카드</b>입니다. 필름 포토·럭키 메시지·이미지 카드·ID 포토·판매처 특전은 완성 목표에서 제외했습니다. 구성표의 포카 종류 합계는 Standard 15 + Limited 10 + QR 35 + Wappen 5 = 65종이며, 공개된 도안 목록이 없어 버전 간 같은 사진 사용 여부는 확인되지 않았습니다.</div></section>`;
}
function summaryText(){return `PULSE FIT · 나의 구매성향 보고서\n${E.profile(answers).name} (성향 ${E.profile(answers).grade})\n예산: ${answers.budgetUnlimited?'무제한':money(answers.budget)} / 최대 ${answers.cap}개\n추천: ${result.offers.length?result.offers.map(o=>o.seller+' '+o.name+(o.quantity?' × '+o.quantity:'')+' ('+o.gift+')').join(' + ')+(result.extras.units?' + 추가 '+basketText(result.extras):''):basketText(result)}\n특전 성향: ${answers.pobKind==='unit'?'유닛':answers.pobKind==='individual'?'개인':'개인·유닛 모두'} / ${answers.pobPriority==='one'?'1종이면 충분':answers.pobPriority==='collect'?'중복 없는 수량 비중 높게':'균형 있게'}\n쇼케이스 계획: ${answers.showcase==='none'?'응모 선택 안 함':(result.showcaseEntries||0)+'회 (구매 계획·컷 미확인)'}${answers.showcase==='target'?' / 개인 목표 '+answers.showcaseTarget+'회':''}\n공구: ${result.groupVenue?result.groupVenue.name:'공구 구매 없음'} / 공구 배송비: ${result.groupShippingUnknown?'미확인':money(result.orderShipping||0)}\n상품 합계: ${money(result.total)} / 별도 예약액: ${money(shipping)}\n실물 ${result.units}개 / 봉입 포카 ${result.cards}장 (중복 포함)\n집계 가능 앨범 ${result.chart}개 (예상·와펜 제외)\n${answers.collect==='complete'?'교환 전제 최소: '+basketText(E.metrics(E.requirements(answers.scope,'yes'),prices,shipping,true))+'\n':''}2026.10.13 확인한 가격·사양 기준. 랜덤 완성 및 초동 반영은 보장되지 않습니다.\n${location.origin+location.pathname}`;}
function compare(){main.innerHTML=heading('FIVE WAYS TO FEEL PULSE','다섯 가지 구매 옵션.','구성은 정확하게, 선택은 취향대로. 가격은 내 판매처 기준으로 수정할 수 있어요.',`<button class="secondary" data-settings>가격 수정 ↗</button>`)+`<div class="product-grid">${E.catalog.map(p=>`<article class="product-card">${art(p.id)}<span class="eyebrow">${p.tag}</span><h2 style="margin-top:10px">${p.name}</h2><div class="product-price">${money(prices[p.id])}</div><ul>${p.contents.map(c=>`<li>${c}</li>`).join('')}</ul><p>${p.note}</p><a class="source-link" href="${p.source}" target="_blank" rel="noopener noreferrer">판매처 구성·가격 확인 ↗</a></article>`).join('')}</div><div class="notice">QR 상품의 짧은 소개 문구에 셀피 1장으로 표시된 곳이 있으나, YES24 세트 상세 사양·케이타운포유·애플뮤직은 <b>15종 중 3장</b>으로 안내합니다. 이 사이트는 상세 사양을 적용합니다. 발매 전 사양이므로 변경될 수 있으며, 주문 전에 실제 상품 상세를 확인하세요.</div>
  ${groupDataSection()}${pobDataSection()}${showcaseDataSection()}<div class="faq"><h2>구매 전에 자주 헷갈리는 것들.</h2><details><summary>QR 5종 세트 하나면 QR 포카가 다 모이나요?</summary><p>패키지 다섯 종류가 각 하나씩 들어 있습니다. 셀피 15장은 랜덤이어서 중복될 수 있고, 버전별 포카는 각 4종 중 2장만 받습니다. 교환 전제의 QR 전종 최소는 각 패키지 두 개인 2세트입니다. 단, 카드 수량을 채운 것이 교환 성사나 완성을 보장하지 않습니다.</p></details><details><summary>Limited가 Standard보다 사진이 많나요?</summary><p>공개 사양에서 Standard는 230 × 300mm, Limited는 182 × 257mm입니다. 페이지 수와 사진의 차이·중복 여부는 확인되지 않아 추천 점수에 사진 수를 반영하지 않았습니다.</p></details><details><summary>와펜도 초동에 반영되나요?</summary><p>공개 구성에는 와펜과 포카만 안내되어 있으며, CD·QR 음원 카드는 보이지 않습니다. 판매처 페이지의 일반 한터 안내만으로 이 상품의 반영을 확정하지 않았습니다. 기본 집계 수량에서는 제외하고, 주문 전 판매처에 상품 단위로 확인하도록 안내합니다.</p></details><details><summary>추천은 어떻게 계산하나요?</summary><p>설문에서 정한 예산·배송 예약액·최대 보관 수량 안의 정수 조합을 전수 비교합니다. 우선순위에 따라 첫 실물 소장, 포카 풀별 수집 효용, 집계 가능 수량에 가중치를 줍니다. 동점이면 더 싼 조합을 선택합니다. 수집 목표가 없으면 같은 구성의 반복 구매 효용을 낮춥니다. QR 묶음과 단품 중 비용이 낮은 조합을 선택하며, QR 전종 수집에서는 패키지가 확보되는 세트를 사용합니다. 가중치는 취향을 반영한 가이드이며 모든 사람에게 동일한 절대 최적값은 아닙니다.</p></details><details><summary>판매처 특전이나 기존에 가진 포카도 계산하나요?</summary><p>새 앨범을 처음 구매하는 경우를 기준으로 계산합니다. 첨부된 특전 세트 7개와 배민·CU·메이크스타 단품 특전은 별도 설문으로 계산합니다. 특전 세트 안의 앨범을 봉입 수집 목표에 합산합니다. 이미 보유한 포카·중고·분철 가격은 포함하지 않습니다. 특전 조건과 보유 도안이 있으면 실제 구매 전략이 달라질 수 있습니다.</p></details><details><summary>내 답변을 저장하나요?</summary><p>답변과 수정한 가격은 이 브라우저에 저장됩니다. 별도 계정·연락처를 수집하지 않습니다. 결과 링크를 복사하면 답변·가격·예산이 링크에 포함되므로 공유할 범위를 확인해 주세요.</p></details></div>${sourcesNote()}`;}
function calculator(){
  main.innerHTML=heading('PHOTOCARD COLLECTION LAB','포카는 몇 개를 사야 모일까?','수량을 직접 바꾸며 카드 장수, 예상 도안 수, 완성 확률을 비교해 보세요.')+`<div class="calc-layout"><aside class="calculator-inputs"><h2>내 구매 조합</h2><label class="field-label">계산할 상품가<select id="calc-shop">${[['auto','공구가 자동 비교'],...E.groupBuys.map(g=>[g.id,g.name])].map(([id,t])=>`<option value="${id}" ${calcShop===id?'selected':''}>${t}</option>`).join('')}</select></label>${E.catalog.map(p=>`<div class="counter-row"><label for="count-${p.id}">${p.name}</label><div class="counter"><button data-count="${p.id}" data-delta="-1" aria-label="${p.name} 수량 줄이기">−</button><input id="count-${p.id}" data-input-count="${p.id}" type="number" min="0" max="100" value="${calcCounts[p.id]}" inputmode="numeric" aria-label="${p.name} 구매 수량"><button data-count="${p.id}" data-delta="1" aria-label="${p.name} 수량 늘리기">+</button></div></div>`).join('')}<p class="small muted" style="margin-top:18px">QR 세트는 5개로 셉니다. 이 계산기는 일반 앨범의 봉입 포카용입니다. 판매처 특전·세트 가격은 구매성향 진단에서 계산합니다. 수량은 설문 추천과 독립적이며 항목별 0~100까지 입력할 수 있어요.</p><div class="button-row" style="margin-top:20px"><button class="text-button" id="calc-zero">전부 비우기</button><button class="text-button" data-settings>가격 변경</button></div></aside><section id="calc-output"></section></div>${sourcesNote()}`;
  document.getElementById('calc-shop').onchange=event=>{calcShop=event.target.value;calcOutput();};
  document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{const k=b.dataset.count;calcCounts[k]=Math.min(100,Math.max(0,calcCounts[k]+Number(b.dataset.delta)));document.getElementById('count-'+k).value=calcCounts[k];calcOutput();});
  document.querySelectorAll('[data-input-count]').forEach(el=>el.oninput=()=>{const n=Number(el.value);if(Number.isInteger(n)&&n>=0&&n<=100){calcCounts[el.dataset.inputCount]=n;calcOutput();}else{document.getElementById('calc-output').innerHTML='<div class="notice coral-notice" role="alert">수량은 0~100 사이의 정수로 입력해 주세요.</div>';}});
  document.getElementById('calc-zero').onclick=()=>{calcCounts=Object.fromEntries(E.catalog.map(p=>[p.id,0]));calculator();};calcOutput();
}
function calcOutput(){
  const c={s:calcCounts.standard,l:calcCounts.limited,q:calcCounts.qr+5*calcCounts.qrset,w:calcCounts.wappen};
  const quote=E.bareQuote(calcCounts,{...answers,groupbuy:calcShop==='auto'?answers.groupbuy:calcShop},prices,shipping),shop=quote.groupVenue;
  const total=quote.total,units=c.s+c.l+c.q+c.w;
  const m={counts:c,qrsets:calcCounts.qrset};
  document.getElementById('calc-output').innerHTML=`<div class="recommend-card"><span class="eyebrow">ALBUM SUBTOTAL</span><div class="total-price" style="margin-top:10px">${money(total)}</div><p class="small muted">미공포 없는 앨범 ${shop?shop.name+' 공구가':'공구 마감 · 일반 가격 참고'} · 공구 배송비 ${quote.groupShippingUnknown?'미확인':money(quote.orderShipping)} · 별도 예약액 ${money(shipping)} · ${quote.groupShippingUnknown?'확인된 금액':'합계'} ${money(quote.checkoutTotal)}${quote.groupShippingUnknown?' + 미확인 배송비':''}</p><div class="stats"><div class="stat"><span>실물 보관 수량</span><b>${units}개</b></div><div class="stat"><span>봉입 포카 · 중복 포함</span><b>${c.s*3+c.l*2+c.q*5+c.w}장</b></div><div class="stat"><span>집계 가능 수량 · 예상</span><b>${c.s+c.l+c.q}개</b></div></div></div><div class="table-wrap"><table><thead><tr><th>수집 풀</th><th>한 팩 구성</th><th>개봉 횟수</th><th>예상 도안 수</th><th>완성 확률</th></tr></thead><tbody>${scopedPoolRows(c,m)}</tbody></table></div>${probabilityNote()}<div class="notice"><b>“10종 중 2장을 주니까 5개면 되겠지?”</b><br>5개는 카드 장수를 채우는 최소 수량입니다. 중복이 생기므로 직접 개봉만으로 10종을 모두 얻을 확률은 ${(E.completion(10,2,5)*100).toFixed(1)}%입니다. 5개 구매 전략은 같은 풀에서의 교환이 가능하다는 가정이 필요해요.</div><p class="data-note">QR 랜덤 단품은 어떤 패키지가 오는지 알 수 없어 버전별 포카 완성 계산에서 제외했습니다. 실제로 확보한 각 패키지의 수량이 같다면 그 수량만큼 세트로 입력할 수 있습니다.</p>`;
}
function sourcesNote(){return `<p class="data-note">미공포 없는 추천·추가 수량·수집 참고값·수량 계산기는 공구가로 계산하며, 미공포·쇼케이스 상품은 해당 이벤트 가격을 유지합니다. 이전 공구 제외 설정도 공구가 자동 비교로 바뀝니다. 공구가·기간·출고·ALL MD 무료배송은 사용자가 제공한 총공 안내 이미지 기준입니다. 미공포·응모 상품과 공구가를 섞어 같은 앨범에 이중 적용하지 않습니다. 일반가 기준: 2026.10.13 확인한 YES24 표시 할인가 및 상품 상세 사양. QR 사양은 <a class="source-link" style="margin:0" href="https://www.ktown4u.com/iteminfo?goods_no=170534" target="_blank" rel="noopener noreferrer">케이타운포유</a>와 <a class="source-link" style="margin:0" href="https://en.applemusic.co.kr/Mobile/Product/Detail/view/pid/121312/cid/102" target="_blank" rel="noopener noreferrer">애플뮤직</a> 안내로 대조했습니다. 발매 전 구성·가격은 변동될 수 있습니다. 배민·CU 단품 특전은 사용자 안내 및 공개 안내와 대조했고, CU QR 5종 세트의 중복 없는 개인 미공포 5장과 CU 와펜 세트의 유닛 미공포 2장은 사용자 안내의 단품당 1장 및 세트 중복 없음 조건으로 수량을 반영합니다. 특전별 합산 수량과 봉입 확률은 별도입니다. 단품 가격은 앱 상품 화면을 직접 조회하지 못해 기본 할인가·세트 단가로 산정한 기준가입니다. CU는 10/14 15:00 오픈 예정 안내를 확인했으며, 실제 판매 상태는 포켓CU에서 확인하세요. 특전 세트 7개는 사용자가 제공한 2026.10.13 안내 이미지 기준이며, 일부 판매처의 개별 증정 조건은 확인이 필요합니다. 메이크스타 털실냥이 단품·5매 중복 없는 조건은 공식 상품 페이지와 대조했습니다. 일반 앨범 가격 변경은 특전 세트의 고정 가격을 바꾸지 않습니다. 가격을 자동 갱신하지 않으며 최저가를 보장하지 않습니다. 이 사이트는 RESCENE 또는 소속사의 공식 서비스가 아닙니다.</p>`;}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('복사했어요.');}catch{const el=document.createElement('textarea');el.value=text;el.style.position='fixed';el.style.opacity='0';document.body.append(el);el.select();try{const ok=document.execCommand('copy');toast(ok?'복사했어요.':'복사를 지원하지 않는 브라우저예요.');}catch{toast('복사를 지원하지 않는 브라우저예요.');}el.remove();}}
let toastTimer;function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function settingsOpen(){document.getElementById('price-fields').innerHTML=E.catalog.map(p=>`<label class="price-field"><span>${p.name} 일반 참고가 (원)</span><input name="${p.id}" type="number" min="100" max="1000000" step="1" value="${prices[p.id]}" required></label>`).join('')+`<p class="small muted">앱 특전 단품 기준가 · 실제 상품 가격으로 수정</p>`+E.pobOffers.filter(o=>o.editablePrice).map(o=>`<label class="price-field"><span>${o.seller} ${o.name}</span><input name="offer_${o.id}" type="number" min="100" max="1000000" step="1" value="${prices['offer_'+o.id]}" required></label>`).join('')+`<label class="field-label">공구 비교<select id="settings-groupbuy">${groupOptions()}</select></label>`+groupFeeFields();document.querySelector('#settings-form [name="shipping"]').value=shipping;document.getElementById('settings').showModal();}
document.getElementById('settings-button').onclick=settingsOpen;
document.getElementById('settings-close').onclick=()=>document.getElementById('settings').close();
document.getElementById('reset-prices').onclick=()=>{for(const p of E.catalog)document.querySelector(`#settings-form [name="${p.id}"]`).value=E.defaultPrices[p.id];for(const o of E.pobOffers.filter(o=>o.editablePrice))document.querySelector(`#settings-form [name="offer_${o.id}"]`).value=E.defaultPrices['offer_'+o.id];};
document.getElementById('settings-form').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget);for(const p of E.catalog){const n=Number(data.get(p.id));if(!Number.isInteger(n)||n<100||n>1000000){toast('가격은 100~1,000,000원 사이의 정수로 입력해 주세요.');return;}}for(const o of E.pobOffers.filter(o=>o.editablePrice)){const n=Number(data.get('offer_'+o.id));if(!Number.isInteger(n)||n<100||n>1000000){toast('앱 단품 가격을 확인해 주세요.');return;}}for(const g of E.groupBuys){const raw=String(data.get('groupShipping_'+g.id)||'').trim(),n=Number(raw);if(raw&&(!Number.isInteger(n)||n<0||n>1000000)){toast('공구 배송비는 빈칸 또는 0~1,000,000원 정수로 입력해 주세요.');return;}}const fee=Number(data.get('shipping'));if(!Number.isInteger(fee)||fee<0||fee>1000000){toast('예약액을 확인해 주세요.');return;}for(const p of E.catalog)prices[p.id]=Number(data.get(p.id));for(const o of E.pobOffers.filter(o=>o.editablePrice))prices['offer_'+o.id]=Number(data.get('offer_'+o.id));shipping=fee;answers.groupbuy=document.getElementById('settings-groupbuy').value;for(const g of E.groupBuys){const raw=String(data.get('groupShipping_'+g.id)||'').trim();answers['groupShipping_'+g.id]=raw?Number(raw):null;}persist();document.getElementById('settings').close();render();toast('새 가격으로 다시 계산했어요.');};
document.addEventListener('click',event=>{const nav=event.target.closest('[data-view]');if(nav){event.preventDefault();if(nav.dataset.view==='quiz')step=0;go(nav.dataset.view);}const settings=event.target.closest('[data-settings]');if(settings)settingsOpen();});
document.addEventListener('keydown',event=>{const active=event.target;if(active.matches('.choice')&&['ArrowDown','ArrowRight','ArrowUp','ArrowLeft'].includes(event.key)){event.preventDefault();const buttons=[...document.querySelectorAll('.choice')];const i=buttons.indexOf(active);const next=(i+(['ArrowDown','ArrowRight'].includes(event.key)?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].click();document.querySelectorAll('.choice')[next].focus();}});
function readShare(){if(!location.hash.startsWith('#r='))return false;try{const raw=location.hash.slice(3);if(raw.length>12000)throw Error('too long');loadState(JSON.parse(decodeURIComponent(raw)));view='result';return true;}catch{toast('결과 링크를 읽지 못했어요. 새로 진단해 주세요.');return false;}}
window.addEventListener('hashchange',()=>{if(readShare())go('result');});
readShare();render();
